import React from 'react'
import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';


const TakeQuiz = () => {

        const location = useLocation();
        const { state: formData } = location;

        const [loading, setLoading] = useState(false);
        const [error, setError] = useState(null); // Error state for managing errors
        const [quizData, setQuizData] = useState(null); // Stores the full response
        const [responseText, setResponseText] = useState(""); // Stores the dynamically displayed text

        const prompt = `Generate a set of quiz questions having 4 choices and 1 correct answer based on the following data given in JSON format : 

        ${JSON.stringify(formData)} 

        Generate the questions in json format.`

        const fetchQuiz = async () => {
                setLoading(true);
                try {
                  const response = await axios({
                    url: "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=YOUR_API_KEY",  // Replace with your actual API key
                    method: "post",
                    data: {
                      contents: [{ parts: [{ text: prompt }] }],
                    },
                  });

                  // Log the entire response for debugging
                  console.log("Full Response:", response);

                  if (response.data && response.data.candidates.length > 0) {
                    // Check structure of returned data and log the contents
                    const content = response.data.candidates[0]?.content?.parts[0]?.text;
                    console.log("Generated Quiz Text:", content);

                    if (content) {
                      setQuizData(content);
                    } else {
                      setError("Content not found in response.");
                    }
                  } else {
                    setError("No candidates returned from the API.");
                  }
                } catch (err) {
                  console.error("Error fetching quiz:", err);
                  setError("An error occurred while fetching the quiz questions.");
                } finally {
                  setLoading(false);
                }
              };

        useEffect(() => {
                if (formData){
                        fetchQuiz();
                }
        },[formData])


        return (
                <div>

<div>
      {loading && <p>Loading...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}
      {quizData && (
        <div>
          <h3>Quiz Questions</h3>
          <pre>{quizData}</pre>
        </div>
      )}
    </div>

                </div>
        )

}

export default TakeQuiz
